    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    def fibonacci_numbers():
        a, b = 0, 1
        while True:
            yield b
            a, b = b, a + b

    prime_fib_count = 0
    for fib in fibonacci_numbers():
        if is_prime(fib):
            prime_fib_count += 1
            if prime_fib_count == n:
                return fib

